import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif

MAX_DRIVERS = 5

def design(feats):
    # Identify strong features based on effect sizes
    strong_features = []
    for i, fid in enumerate(feats.ids):
        # Check if this is a numerical feature type
        try:
            effect_size = feats.types[i]
            if isinstance(effect_size, (int, float)) and abs(effect_size) > 0.5:
                strong_features.append((fid, effect_size))
        except:
            # Skip non-numerical types
            continue

    # Sort by absolute effect size
    strong_features.sort(key=lambda x: abs(x[1]), reverse=True)

    # Group correlated features
    correlated_groups = []
    used = set()

    # Build correlation matrix
    corr_matrix = np.corrcoef(feats.x.T)

    # Find clusters of highly correlated features
    for i, fid1 in enumerate(feats.ids):
        if fid1 in used:
            continue
        group = [fid1]
        used.add(fid1)

        for j, fid2 in enumerate(feats.ids):
            if i != j and fid2 not in used and abs(corr_matrix[i,j]) >= 0.6:
                group.append(fid2)
                used.add(fid2)

        if len(group) > 1:
            correlated_groups.append(group)

    # For each group, select the strongest feature
    selected_features = []
    for group in correlated_groups:
        # Select feature with highest absolute effect size
        best_fid = max(group, key=lambda fid: abs(feats.types[feats.column(fid)]))
        selected_features.append(best_fid)

    # Add uncorrelated strong features
    for fid, effect_size in strong_features:
        if fid not in selected_features:
            selected_features.append(fid)

    # Select top 5 features for drivers
    drivers = tuple(selected_features[:MAX_DRIVERS])

    # Select all features for logistic regression
    columns = tuple(selected_features)

    # Create interaction terms for strongly correlated pairs
    products = []
    for i, fid1 in enumerate(columns):
        for j, fid2 in enumerate(columns):
            if i < j:
                try:
                    corr = np.corrcoef(feats.x[:, feats.column(fid1)], feats.x[:, feats.column(fid2)])[0,1]
                    if abs(corr) >= 0.6:
                        products.append((fid1, fid2))
                except:
                    continue

    # Calculate loadings using mutual information
    loadings = {}
    for fid in columns:
        try:
            mi = mutual_info_classif(
                feats.x[:, feats.column(fid)].reshape(-1, 1), 
                feats.y
            )[0]
            loadings[fid] = mi
        except:
            # If mutual info fails, use effect size as loading
            loadings[fid] = abs(feats.types[feats.column(fid)])

    return Design(
        drivers=drivers,
        columns=columns,
        products=tuple(products),
        loadings=loadings
    )
